<?php if (!$history['total']): ?><div class="empty-state compact"><h3>Nenhuma movimentação registrada</h3><p>Entradas e saídas aparecerão aqui com data, motivo e saldo.</p></div><?php else: ?><div class="table-responsive mt-3"><table class="table align-middle"><thead><tr><th scope="col">Data</th><?php if ($page==='history'): ?><th scope="col">Livro</th><?php endif; ?><th scope="col">Tipo</th><th scope="col">Qtd.</th><th scope="col">Saldo após</th><th scope="col">Motivo / observação</th></tr></thead><tbody><?php foreach ($history['movements'] as $movement): ?><tr><td class="text-nowrap"><?= date('d/m/Y',strtotime($movement['created_at'])) ?><small class="d-block text-secondary"><?= date('H:i',strtotime($movement['created_at'])) ?></small></td><?php if ($page==='history'): ?><td><a href="<?= e(url(['page'=>'book','id'=>$movement['book_id']])) ?>"><?= e($movement['title']) ?></a></td><?php endif; ?><td><span class="badge <?= $movement['type']==='entrada' ? 'text-bg-success' : 'text-bg-secondary' ?>"><?= $movement['type']==='entrada' ? 'Entrada' : 'Saída' ?></span></td><td><?= $movement['quantity'] ?></td><td><?= $movement['balance_after'] ?></td><td><?= e($movement['reason']) ?><?php if ($movement['note']): ?><small class="d-block text-secondary preserve-lines"><?= e($movement['note']) ?></small><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
